/* @lc app=leetcode id=4053 lang=kotlin */ class Solution { fun minOperations(nums: IntArray): Long = (1..10).flatMap { len -> ((len + 1) / 2).let { h -> ("1".padEnd(h, '0').toLong() until "1".padEnd(h + 1, '0').toLong()).map { p -> p.toString().let { s -> (s + s.reversed().drop(len % 2)).toLong() } } } }.let { pals -> pals.filter { it % 2 == 0L }.let { ev -> pals.filter { it % 2 == 1L }.let { od -> nums.sumOf { x -> (if (x % 2 == 0) ev else od).let { l -> l.binarySearch(x.toLong()).let { r -> (if (r >= 0) r else -r - 1).let { ins -> listOfNotNull(l.getOrNull(ins), l.getOrNull(ins - 1)).minOf { Math.abs(it - x) } / 2 } } } } } } } }